  const allNames=new Set([...histories.keys(),...state.competitionRecords.map(r=>r.memberName)]);
  state.members=[...allNames].filter(name=>!isDormantMember(name)).sort((a,b)=>a.localeCompare(b,"ko")).map(memberName=>({memberName,recordCount:(histories.get(memberName)||[]).length,pb:Object.fromEntries(state.events.map(e=>[e.event_id,best.get(memberName+"\0"+e.event_id)||null]))}));
