  state.competitionRecords.forEach(r=>{if(!competitionMap.has(r.memberName))competitionMap.set(r.memberName,{memberName:r.memberName,attendance:0,coxCount:0,gold:0,silver:0,bronze:0,medalKeys:new Set()});const m=competitionMap.get(r.memberName),competitionNameKey=String(r.competitionName||"").trim().replace(/\s+/g," ").toLocaleLowerCase("ko"),attendanceKey=r.memberName+"\0"+r.year+"\0"+competitionNameKey+"\0"+r.competitionType,boatKey=r.year+"\0"+r.competitionId+"\0"+r.competitionType+"\0"+r.competitionEventId+"\0"+r.competitionDivisionId+"\0"+(r.note||"");if(!attendanceKeys.has(attendanceKey)){attendanceKeys.add(attendanceKey);m.attendance++;}const coxKey=r.memberName+"\0"+boatKey;if(r.isCox&&!coxKeys.has(coxKey)){coxKeys.add(coxKey);m.coxCount++;}if(r.competitionType==="indoor"&&state.excludeIndoorMedals)return;["gold","silver","bronze"].forEach(color=>{if(r[color]<=0)return;const memberKey=r.memberName+"\0"+boatKey+"\0"+color;if(!m.medalKeys.has(memberKey)){m.medalKeys.add(memberKey);m[color]++;}clubMedalKeys.add(boatKey+"\0"+color);});});
