  const indoor=state.competitionSummaryType==="indoor",rawDivisions=state.competitionDivisions.filter(d=>competitionDivisionType(d)===state.competitionSummaryType),groupedDivisions=new Map();rawDivisions.forEach(division=>{const heading=divisionHeading(division);if(!groupedDivisions.has(heading.group))groupedDivisions.set(heading.group,[]);groupedDivisions.get(heading.group).push({...division,shortName:heading.label});});const groupOrder=["남자","여자","혼성","기타"],divisionGroups=[...groupedDivisions].map(([name,groupDivisions])=>({name,divisions:groupDivisions.sort((a,b)=>a.shortName.includes("일반부")-b.shortName.includes("일반부"))})).sort((a,b)=>groupOrder.indexOf(a.name)-groupOrder.indexOf(b.name)),divisions=divisionGroups.flatMap(group=>group.divisions),table=$(".medal-matrix");state.competitionLineups=new Map();table.style.setProperty("--division-count",divisions.length);table.classList.toggle("is-indoor",indoor);
