function athleteRole(memberName) { const rows=state.competitionRecords.filter(row=>row.memberName===memberName),hasCox=rows.some(row=>row.isCox),hasCrew=rows.some(row=>!row.isCox);return hasCox&&hasCrew?"COX · CREW":hasCox?"COX":hasCrew?"CREW":"회원"; }
function athleteHasPbImprovement(memberName) { return state.events.some(event=>{const rows=state.records.filter(row=>row.memberName===memberName&&row.eventId===event.event_id&&row.timeMs).sort((a,b)=>String(a.competition_date).localeCompare(String(b.competition_date))),seen=[];return rows.some(row=>{const improved=seen.length&&row.timeMs<Math.min(...seen);seen.push(row.timeMs);return improved;});}); }
function athleteHasGrowth(memberName) { return state.events.some(event=>{const rows=state.records.filter(row=>row.memberName===memberName&&row.eventId===event.event_id&&row.timeMs).sort((a,b)=>String(a.competition_date).localeCompare(String(b.competition_date)));return rows.length>1&&(rows[0].timeMs-Math.min(...rows.map(row=>row.timeMs)))/rows[0].timeMs>=.05;}); }
function athleteBadgeData(member) { const records=state.records.filter(row=>row.memberName===member.memberName),summary=athleteCompetitionSummary(member.memberName),types=Object.values(summary.types),training=[{name:"오각형 완성",image:"static/badges/pentagon-complete.png",earned:state.events.length>0&&state.events.every(event=>member.pb[event.event_id]),rule:"모든 에르고 종목 PB 보유"},{name:"PB 갱신",image:"static/badges/pb-update.png",earned:athleteHasPbImprovement(member.memberName),rule:"기존 개인기록 경신"},{name:"윈터 챌린지",image:"static/badges/winter-challenge.png",earned:records.some(row=>[12,1,2].includes(Number(String(row.competition_date||"").slice(5,7)))),rule:"12~2월 기록 참여"},{name:"성장왕",image:"static/badges/growth-champion.png",earned:athleteHasGrowth(member.memberName),rule:"동일 종목 기록 5% 이상 향상"}],competition=[{name:"첫 출전",image:"static/badges/first-start.png",earned:summary.total.attendance>0,rule:"대회 최초 출전"},{name:"첫 메달",image:"static/badges/first-medal.png",earned:summary.total.gold+summary.total.silver+summary.total.bronze>0,rule:"첫 대회 메달 획득"},{name:"금빛 질주",image:"static/badges/golden-sprint.png",earned:summary.total.gold>0,rule:"금메달 획득"},{name:"멀티 레이서",image:"static/badges/multi-racer.png",earned:types.every(type=>type.attendance>0),rule:"수상·실내·비치 모두 출전"},{name:"그랜드 슬램",image:"static/badges/grand-slam.png",earned:types.every(type=>type.gold+type.silver+type.bronze>0),rule:"세 대회 유형에서 모두 메달"}];return {training,competition}; }
function athleteRadar(member) { const events=state.events.slice().sort(eventNameCompare).slice(0,5);if(events.length<3)return '<p class="athlete-empty-note">오각형을 만들려면 3개 이상의 종목이 필요합니다.</p>';const cx=130,cy=125,radius=78,labelRadius=105,point=(index,r)=>{const angle=-Math.PI/2+Math.PI*2*index/events.length;return [cx+Math.cos(angle)*r,cy+Math.sin(angle)*r]},polygon=values=>values.map((value,index)=>point(index,radius*value/100).map(number=>number.toFixed(1)).join(",")).join(" "),outer=polygon(events.map(()=>100)),scores=events.map(event=>{const rows=state.rankings[event.event_id]||[],row=rows.find(item=>item.memberName===member.memberName);return !row?0:rows.length<=1?100:Math.max(20,100-(row.rank-1)/(rows.length-1)*80);});return `<svg class="athlete-radar-svg" viewBox="0 0 260 250" role="img" aria-label="${esc(member.memberName)} 종목별 상대 기록">${[.25,.5,.75,1].map(scale=>`<polygon class="radar-ring" points="${polygon(events.map(()=>scale*100))}"></polygon>`).join("")}${events.map((event,index)=>{const [x,y]=point(index,radius);return `<line class="radar-axis" x1="${cx}" y1="${cy}" x2="${x}" y2="${y}"></line>`;}).join("")}<polygon class="radar-value" points="${polygon(scores)}"></polygon>${scores.map((score,index)=>{const [x,y]=point(index,radius*score/100);return `<circle class="radar-point" cx="${x}" cy="${y}" r="4"></circle>`;}).join("")}${events.map((event,index)=>{const [x,y]=point(index,labelRadius);return `<text class="radar-label" x="${x}" y="${y}" text-anchor="middle">${esc(event.event_name)}</text>`;}).join("")}</svg>`; }
