function renderAthleteList() { const query=$("#athleteSearch").value.trim().toLocaleLowerCase("ko"),members=state.members.filter(member=>memberNameMatches(member.memberName,query));$("#athleteCount").textContent=`${members.length}명`;$("#athleteList").innerHTML=members.map(member=>{const medals=athleteCompetitionSummary(member.memberName).total;return `<button class="athlete-list-item ${member.memberName===state.athleteSelectedName?"is-active":""}" type="button" data-athlete-name="${esc(member.memberName)}"><strong>${esc(member.memberName)}</strong><span>PB ${Object.values(member.pb).filter(Boolean).length} · 출전 ${medals.attendance} · 메달 ${medals.gold+medals.silver+medals.bronze}</span></button>`;}).join("")||'<p class="athlete-empty-note">검색된 선수가 없습니다.</p>'; }
