function renderAthleteComparison() { const primary=state.members.find(member=>member.memberName===state.athleteSelectedName),secondary=state.members.find(member=>member.memberName===state.athleteCompareName);$("#athletePrimarySelect").value=primary?.memberName||"";$("#athleteSecondarySelect").value=secondary?.memberName||"";if(!primary||!secondary){$("#athleteComparison").innerHTML='<p class="athlete-empty-note">비교할 두 선수를 선택해 주세요.</p>';return;}const events=state.events.slice().sort(eventNameCompare);$("#athleteComparison").innerHTML=`<div class="athlete-compare-names"><strong>${esc(primary.memberName)}</strong><span>VS</span><strong>${esc(secondary.memberName)}</strong></div><div class="athlete-compare-table">${events.map(event=>{const left=primary.pb[event.event_id],right=secondary.pb[event.event_id],both=left&&right,leftWins=both&&left.timeMs<right.timeMs,rightWins=both&&right.timeMs<left.timeMs,leftWidth=both?Math.min(100,right.timeMs/left.timeMs*88):0,rightWidth=both?Math.min(100,left.timeMs/right.timeMs*88):0;return `<div class="athlete-compare-row"><strong class="athlete-compare-event">${esc(event.event_name)}</strong><div class="athlete-compare-result left ${leftWins?"is-winner":""}"><span>${esc(left?.timeDisplay||"없음")}</span>${both?`<i style="width:${leftWidth}%"></i>`:""}</div><div class="athlete-compare-result right ${rightWins?"is-winner":""}"><span>${esc(right?.timeDisplay||"없음")}</span>${both?`<i style="width:${rightWidth}%"></i>`:""}</div></div>`;}).join("")}</div>`; }
