  const raceOptions='<option value="" selected disabled>대회 선택</option><option value="__new__">새 대회 등록</option>'+state.competitions.slice().sort((a,b)=>a.competition_name.localeCompare(b.competition_name,"ko")).map(c=>`<option value="${esc(c.competition_id)}">${esc(c.competition_name)}</option>`).join("");$("#bulkRaceSelect").innerHTML=raceOptions;
  renderCompetitionCatalogOptions();
