function competitionMemberSearchKey(value) {
  const initials=[..."ㄱㄲㄴㄷㄸㄹㅁㅂㅃㅅㅆㅇㅈㅉㅊㅋㅌㅍㅎ"],vowels=[..."ㅏㅐㅑㅒㅓㅔㅕㅖㅗㅘㅙㅚㅛㅜㅝㅞㅟㅠㅡㅢㅣ"],finals=["ㄱ","ㄲ","ㄱㅅ","ㄴ","ㄴㅈ","ㄴㅎ","ㄷ","ㄹ","ㄹㄱ","ㄹㅁ","ㄹㅂ","ㄹㅅ","ㄹㅌ","ㄹㅍ","ㄹㅎ","ㅁ","ㅂ","ㅂㅅ","ㅅ","ㅆ","ㅇ","ㅈ","ㅊ","ㅋ","ㅌ","ㅍ","ㅎ"];
  return [...String(value).trim().toLocaleLowerCase("ko").normalize("NFD")].map(char=>{const code=char.codePointAt(0);return initials[code-0x1100]||vowels[code-0x1161]||finals[code-0x11a8]||char;}).join("");
}
function memberNameMatches(name,query) {
  const normalized=competitionMemberSearchKey(query),initialsOnly=/^[ㄱㄲㄴㄷㄸㄹㅁㅂㅃㅅㅆㅇㅈㅉㅊㅋㅌㅍㅎ]+$/.test(normalized);
  const nameInitials=name=>[...name].map(char=>{const code=char.codePointAt(0)-0xac00;return code>=0&&code<11172?"ㄱㄲㄴㄷㄸㄹㅁㅂㅃㅅㅆㅇㅈㅉㅊㅋㅌㅍㅎ"[Math.floor(code/588)]:char;}).join("");
  return initialsOnly?nameInitials(name).includes(normalized):competitionMemberSearchKey(name).includes(normalized);
}
async function api(action,payload={},admin=false) { return window.ClubApi.call(action,payload,admin?state.adminToken:""); }
async function compress(file) {
  if(!file)return null;
  if(file.size>10*1024*1024)throw new Error("증빙사진은 원본 파일 기준 10MB 이하여야 합니다.");
  const image=await createImageBitmap(file),limit=150*1024;
  let scale=Math.min(1,1600/Math.max(image.width,image.height)),blob=null;
  try {
    // Try quality adjustments before sacrificing the size of the lettering.
    for(let pass=0;pass<12;pass++) {
      const c=document.createElement("canvas");c.width=Math.max(1,Math.round(image.width*scale));c.height=Math.max(1,Math.round(image.height*scale));c.getContext("2d").drawImage(image,0,0,c.width,c.height);
      for(const quality of [.82,.74,.66,.58,.50,.42]) {
        blob=await new Promise(r=>c.toBlob(r,"image/jpeg",quality));
        if(!blob)throw new Error("사진을 처리하지 못했습니다.");
        if(blob.size<=limit)break;
      }
      if(blob.size<=limit)break;
      scale*=.8;
    }
    if(!blob||blob.size>limit)throw new Error("사진을 150KB 이하로 압축하지 못했습니다.");
    const base64=await new Promise((ok,no)=>{const r=new FileReader();r.onload=()=>ok(String(r.result).split(",")[1]);r.onerror=no;r.readAsDataURL(blob);});
    return {name:file.name.replace(/\.[^.]+$/,"")+".jpg",mimeType:"image/jpeg",base64};
  } finally { if(image.close)image.close(); }
}
async function fetchWithTimeout(url) { const controller=new AbortController(),timeout=window.setTimeout(()=>controller.abort(),12000);try{return await fetch(url,{cache:"no-store",signal:controller.signal});}finally{window.clearTimeout(timeout);} }
async function latestRevision() { try{const r=await fetchWithTimeout(`${GITHUB_COMMIT_URL}?_=${Date.now()}`),d=await r.json();return /^[a-f0-9]{40}$/i.test(d.sha||"")?d.sha:"main";}catch{return "main";} }
async function fetchCsv(name,revision) { const local=["localhost","127.0.0.1"].includes(location.hostname),url=local?`data/${name}?_=${Date.now()}`:`https://raw.githubusercontent.com/firefly247/src-leaderboard/${revision}/data/${name}?_=${Date.now()}`,r=await fetchWithTimeout(url);if(!r.ok)throw new Error(`${name} 파일을 불러오지 못했습니다.`);return r.text(); }
async function loadRecordFiles() {
  const names=["events.csv","records.csv","competitions.csv","competition_events.csv","competition_divisions.csv","competition_records.csv","competition_dates.csv","dormant_members.csv"];
  const local=["localhost","127.0.0.1"].includes(location.hostname);
  if(local&&!window.ClubApi?.ready)return Promise.all(names.map(n=>fetchCsv(n,"main")));
  return window.ClubApi.publicFiles();
}
async function refresh(manual=false) { if(state.refreshing)return;const b=$("#refreshButton"),s=$("#statusMessage");state.refreshing=true;b.disabled=true;b.setAttribute("aria-busy","true");if(manual){s.hidden=false;s.classList.remove("status-error");s.textContent="최신 기록을 확인하는 중입니다.";}try{const files=await loadRecordFiles();state.events=csvObjects(files[0]).filter(e=>e.event_id&&e.event_name).sort(eventNameCompare);state.records=csvObjects(files[1]).map(record).filter(r=>r.memberName&&r.eventId&&r.timeMs>0);state.competitions=csvObjects(files[2]).filter(c=>c.competition_id&&c.competition_name);state.competitionEvents=csvObjects(files[3]).filter(e=>e.competition_event_id&&e.competition_event_name);state.competitionDivisions=csvObjects(files[4]).filter(d=>d.competition_division_id&&d.competition_division_name);state.competitionRecords=csvObjects(files[5]).map(competitionRecord).filter(r=>r.memberName&&r.competitionId&&r.competitionEventId&&r.competitionDivisionId&&r.year);state.competitionDates=csvObjects(files[6]);state.dormantMembers=new Set(csvObjects(files[7]).map(row=>row.member_name));build();render();applyDormantMemberVisibility();if(manual)s.hidden=true;api("pendingDeleteRecords").then(d=>state.pendingDeleteIds=new Set(d.recordIds||[])).catch(()=>{});}catch(e){s.hidden=false;s.classList.add("status-error");s.textContent=e.message;console.error(e);}finally{state.refreshing=false;state.refreshedAt=Date.now();b.disabled=false;b.removeAttribute("aria-busy");} }
function result(selector,message,bad=false) { const e=$(selector);e.textContent=message;e.classList.toggle("is-error",bad); }

function playerJoinYearSummaryHtml(players) {
  const groups=new Map();players.forEach(player=>{const year=String(player.joinYear||"");if(!groups.has(year))groups.set(year,[]);groups.get(year).push(player.memberName);});
  const years=[...groups.keys()].sort((a,b)=>a===""?1:b===""?-1:Number(a)-Number(b)),height=Math.max(0,...[...groups.values()].map(names=>names.length));
  groups.forEach(names=>names.sort((a,b)=>a.localeCompare(b,"ko")));
  return `<p class="player-summary-total">총 ${players.length}명</p><div class="table-wrap"><table class="player-join-table"><thead><tr>${years.map(year=>`<th>${year?esc(year)+"년":"미입력"}<small>${groups.get(year).length}명</small></th>`).join("")}</tr></thead><tbody>${Array.from({length:height},(_,index)=>`<tr>${years.map(year=>`<td>${esc(groups.get(year)[index]||"")}</td>`).join("")}</tr>`).join("")||'<tr><td class="empty-cell">등록된 선수가 없습니다.</td></tr>'}</tbody></table></div>`;
}
