document.addEventListener("click",e=>{const button=e.target.closest("[data-birth-year-step],[data-join-year-step]");if(button){const join=button.hasAttribute("data-join-year-step"),input=button.closest(".birth-year-control").querySelector(join?".join-year-input":".birth-year-input");if(join)stepJoinYear(input,Number(button.dataset.joinYearStep));else stepBirthYear(input,Number(button.dataset.birthYearStep));}});
